import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def normalized(value: str) -> str:
        return re.sub(r"[^a-z0-9]+", " ", value.lstrip("\ufeff").lower()).strip()

    header_index = None
    for index, record in enumerate(records):
        fields = [normalized(value) for value in record]
        if len(fields) >= 3:
            if (
                fields[0] == "district"
                and "buffer" in fields[1]
                and "extent" in fields[1]
                and "description" in fields[1]
                and "speed" in fields[2]
                and "limit" in fields[2]
                and "mph" in fields[2]
            ):
                header_index = index
                break

    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if any(value.strip() for value in record)),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    data_records = records[header_index + 1 :]
    width = max(4, len(columns), *(len(record) for record in data_records)) if data_records else max(4, len(columns))

    columns.extend("" for _ in range(width - len(columns)))
    for index in range(len(records[header_index]), width):
        columns[index] = f"Column {index + 1}"

    rows = []
    for record in data_records:
        row = list(record[:width])
        row.extend("" for _ in range(width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
